const providerOAuthCrypto = require('crypto');
const PROVIDER_OAUTH_REQUIRED_SCOPE = 'salesforce.integration';
const PROVIDER_OAUTH_TOKEN_TTL_SECONDS = 900;

function providerOAuthEnv(name) {
  try { return String($env[name] || ''); } catch (error) { return ''; }
}

function providerOAuthHeader(headers, name) {
  const target = name.toLowerCase();
  for (const [key, value] of Object.entries(headers || {})) {
    if (String(key).toLowerCase() === target) return Array.isArray(value) ? value[0] : value;
  }
  return '';
}

function providerOAuthScopes(value) {
  return [...new Set(String(value || '').trim().split(/\s+/).filter(Boolean))];
}

function providerOAuthBase64Url(value) {
  return Buffer.from(value).toString('base64').replace(/=/g, '').replace(/\+/g, '-').replace(/\//g, '_');
}

function providerOAuthDecodeSegment(segment) {
  if (!/^[A-Za-z0-9_-]+$/.test(String(segment || ''))) throw new Error('invalid base64url');
  const padding = (4 - (segment.length % 4)) % 4;
  const decoded = Buffer.from(segment + '='.repeat(padding), 'base64');
  if (providerOAuthBase64Url(decoded) !== segment) throw new Error('non-canonical base64url');
  return decoded;
}

function providerOAuthFailure(statusCode, error, description) {
  return { ok: false, statusCode, body: { error, error_description: description } };
}

function providerOAuthInvalidToken() {
  return providerOAuthFailure(401, 'invalid_token', 'The access token is invalid or expired.');
}

function validateProviderBearerJwt(request) {
  const jwtSecret = providerOAuthEnv('RENOV_OAUTH_JWT_SECRET');
  const issuer = providerOAuthEnv('RENOV_OAUTH_ISSUER');
  const audience = providerOAuthEnv('RENOV_OAUTH_AUDIENCE');
  const configuredClientId = providerOAuthEnv('RENOV_OAUTH_CLIENT_ID');
  const configuredScopes = providerOAuthScopes(providerOAuthEnv('RENOV_OAUTH_SCOPE'));
  const allowedClientIds = providerOAuthEnv('RENOV_PROVIDER_CLIENT_IDS')
    .split(',')
    .map((value) => value.trim().toLowerCase())
    .filter(Boolean);

  if (!jwtSecret || !issuer || !audience || !configuredClientId
      || !configuredScopes.includes(PROVIDER_OAUTH_REQUIRED_SCOPE)
      || allowedClientIds.length === 0) {
    return providerOAuthFailure(503, 'server_error', 'OAuth server configuration is unavailable.');
  }

  const headers = request && request.headers && typeof request.headers === 'object' ? request.headers : {};
  const authorization = String(providerOAuthHeader(headers, 'authorization') || '');
  const bearerMatch = authorization.match(/^Bearer[ \t]+([^ \t]+)[ \t]*$/i);
  const xClientId = String(providerOAuthHeader(headers, 'x-client-id') || '').trim().toLowerCase();
  if (!bearerMatch || !xClientId || !allowedClientIds.includes(xClientId)) return providerOAuthInvalidToken();

  const token = bearerMatch[1];
  const parts = token.split('.');
  if (parts.length !== 3) return providerOAuthInvalidToken();

  let header;
  let payload;
  let signature;
  try {
    header = JSON.parse(providerOAuthDecodeSegment(parts[0]).toString('utf8'));
    payload = JSON.parse(providerOAuthDecodeSegment(parts[1]).toString('utf8'));
    signature = providerOAuthDecodeSegment(parts[2]);
  } catch (error) {
    return providerOAuthInvalidToken();
  }
  if (!header || typeof header !== 'object' || Array.isArray(header) || header.alg !== 'HS256') {
    return providerOAuthInvalidToken();
  }
  if (!payload || typeof payload !== 'object' || Array.isArray(payload)) return providerOAuthInvalidToken();

  const expectedSignature = providerOAuthCrypto
    .createHmac('sha256', jwtSecret)
    .update(parts[0] + '.' + parts[1], 'utf8')
    .digest();
  if (signature.length !== expectedSignature.length
      || !providerOAuthCrypto.timingSafeEqual(signature, expectedSignature)) {
    return providerOAuthInvalidToken();
  }

  if (payload.iss !== issuer || payload.aud !== audience
      || typeof payload.sub !== 'string' || typeof payload.client_id !== 'string'
      || payload.sub !== configuredClientId || payload.client_id !== configuredClientId
      || payload.sub !== payload.client_id) {
    return providerOAuthInvalidToken();
  }

  const tokenScopes = providerOAuthScopes(payload.scope);
  if (!tokenScopes.includes(PROVIDER_OAUTH_REQUIRED_SCOPE)
      || !tokenScopes.every((scope) => configuredScopes.includes(scope))) {
    return providerOAuthFailure(403, 'insufficient_scope', 'The access token lacks the required scope.');
  }

  const numericDatesAreValid = Number.isSafeInteger(payload.iat)
    && Number.isSafeInteger(payload.nbf)
    && Number.isSafeInteger(payload.exp);
  const now = Math.floor(Date.now() / 1000);
  if (!numericDatesAreValid
      || payload.nbf !== payload.iat
      || payload.exp - payload.iat !== PROVIDER_OAUTH_TOKEN_TTL_SECONDS
      || payload.iat > now
      || payload.nbf > now
      || payload.exp <= now) {
    return providerOAuthInvalidToken();
  }

  return {
    ok: true,
    clientId: payload.client_id,
    providerClientId: xClientId,
    scope: tokenScopes.join(' '),
    claims: payload,
  };
}

const providerOAuthRequest = $input.first().json || {};
const providerOAuthAuth = validateProviderBearerJwt(providerOAuthRequest);
if (!providerOAuthAuth.ok) {
  return [{ json: { statusCode: providerOAuthAuth.statusCode, body: providerOAuthAuth.body, authorized: false } }];
}

