// REUSABLE SNIPPET — kept identical to AUTH-01 / UTIL-02.
// Contract: docs/CONTRATO_API_SALESFORCE.md, "Autenticacion (T-1.17)".
// =====================================================================
function response(statusCode, body) {
  return [{ json: { statusCode, body } }];
}
function apiError(statusCode, code, message, details = []) {
  return response(statusCode, { code, message, details });
}
// ======================= end of reusable snippet =======================

const request = $input.first().json || {};
const query = request.query ?? {};

const UUID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

const jobId = String(query.jobId ?? query.job_id ?? '').trim();
const sfDispatchId = String(query.sfDispatchId ?? query.sf_dispatch_id ?? query.dispatchId ?? '').trim();

if (!jobId && !sfDispatchId) {
  return apiError(422, 'MISSING_REQUIRED_FIELD', 'Indique jobId o sfDispatchId.');
}
if (jobId && sfDispatchId) {
  return apiError(422, 'AMBIGUOUS_IDENTIFIER', 'Indique jobId o sfDispatchId, no ambos.');
}
// The SQL casts $1 to uuid: an unparseable value must never reach PostgreSQL.
if (jobId && !UUID_PATTERN.test(jobId)) {
  return apiError(422, 'INVALID_JOB_ID', 'jobId debe ser un UUID.');
}
if (sfDispatchId && sfDispatchId.length > 255) {
  return apiError(422, 'INVALID_DISPATCH_ID', 'sfDispatchId excede la longitud admitida.');
}

return [{
  json: {
    statusCode: 200,
    ok: true,
    job_id: jobId || null,
    sf_dispatch_id: sfDispatchId || null,
    sql: "-- Read-only status of a single dispatch, for support and reconciliation.\n--\n-- Extension outside the committed T-1.18 contract; see\n-- docs/CONTRATO_API_SALESFORCE.md, \"Extensiones fuera del contrato comprometido\".\n-- Consumed by UTIL-03. Accepts either identifier: $1 is the provider job_id and\n-- $2 is the sf_dispatchId Salesforce supplied as the idempotency key.\n--\n-- Never returns prices, promotions or recipient phone numbers: the failure list\n-- is keyed by the Salesforce account id the caller already owns.\nWITH requested AS (\n  SELECT\n    nullif(btrim($1::text), '')::uuid AS job_id,\n    nullif(btrim($2::text), '')       AS sf_dispatch_id\n)\nSELECT\n  dispatch.id::text            AS job_id,\n  dispatch.sf_dispatch_id      AS sf_dispatch_id,\n  dispatch.salesforce_campaign_id,\n  dispatch.campaign_name,\n  dispatch.segment_month::text AS segment_month,\n  dispatch.template_name,\n  dispatch.status::text        AS status,\n  dispatch.requested_count,\n  dispatch.accepted_count,\n  dispatch.rejected_count,\n  dispatch.rejections,\n  dispatch.worker_attempt_count,\n  dispatch.last_http_status,\n  dispatch.last_error,\n  dispatch.requested_at,\n  dispatch.started_at,\n  dispatch.completed_at,\n  dispatch.next_attempt_at,\n  coalesce(counts.by_status, '{}'::jsonb) AS delivery_counts,\n  coalesce(failures.items, '[]'::jsonb)   AS delivery_failures\nFROM renovation_dev.quicklink_campaign_dispatches AS dispatch\nCROSS JOIN requested\nLEFT JOIN LATERAL (\n  SELECT jsonb_object_agg(grouped.status, grouped.total) AS by_status\n  FROM (\n    SELECT item.status::text AS status, count(*) AS total\n    FROM renovation_dev.quicklink_campaign_dispatch_items AS item\n    WHERE item.dispatch_id = dispatch.id\n    GROUP BY item.status\n  ) AS grouped\n) AS counts ON true\nLEFT JOIN LATERAL (\n  SELECT jsonb_agg(\n    jsonb_build_object(\n      'sf_accountId', recent.salesforce_customer_id,\n      'status', recent.status,\n      'reason', recent.reason\n    )\n  ) AS items\n  FROM (\n    SELECT\n      item.salesforce_customer_id,\n      item.status::text                                 AS status,\n      coalesce(item.reject_reason, item.last_error)     AS reason,\n      item.updated_at\n    FROM renovation_dev.quicklink_campaign_dispatch_items AS item\n    WHERE item.dispatch_id = dispatch.id\n      AND (\n        item.status = 'failed'::renovation_dev.delivery_status\n        OR item.reject_reason IS NOT NULL\n      )\n    ORDER BY item.updated_at DESC\n    LIMIT 50\n  ) AS recent\n) AS failures ON true\nWHERE (requested.job_id IS NOT NULL AND dispatch.id = requested.job_id)\n   OR (requested.sf_dispatch_id IS NOT NULL AND dispatch.sf_dispatch_id = requested.sf_dispatch_id)\nLIMIT 1",
    query_params: [jobId || null, sfDispatchId || null],
  },
}];

// Shapes the dispatch status response documented in
// docs/CONTRATO_API_SALESFORCE.md, "Extensiones fuera del contrato comprometido".
// Mirrors the field names of the 202 body of POST /v1/campaigns/dispatch so
// Salesforce reads one vocabulary. Never returns prices, promotions or phones.
const row = $input.first().json ?? {};

if (!row || !row.job_id) {
  return [{
    json: {
      statusCode: 404,
      body: {
        code: 'DISPATCH_NOT_FOUND',
        message: 'No existe un lote con ese identificador.',
        details: [],
      },
    },
  }];
}

return [{
  json: {
    statusCode: 200,
    body: {
      job_id: row.job_id,
      sf_dispatchId: row.sf_dispatch_id ?? null,
      sf_campaignId: row.salesforce_campaign_id ?? null,
      campaignName: row.campaign_name ?? null,
      monthSegment: row.segment_month ?? null,
      templateId: row.template_name ?? null,
      status: String(row.status ?? '').toUpperCase(),
      received: row.requested_count ?? 0,
      accepted: row.accepted_count ?? 0,
      rejected: row.rejected_count ?? 0,
      rejectedItems: Array.isArray(row.rejections) ? row.rejections : [],
      deliveryCounts: row.delivery_counts ?? {},
      deliveryFailures: Array.isArray(row.delivery_failures) ? row.delivery_failures : [],
      attempts: row.worker_attempt_count ?? 0,
      lastHttpStatus: row.last_http_status ?? null,
      lastError: row.last_error ?? null,
      requestedAt: row.requested_at ?? null,
      startedAt: row.started_at ?? null,
      completedAt: row.completed_at ?? null,
      nextAttemptAt: row.next_attempt_at ?? null,
    },
  },
}];
